head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil17102";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil17102.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_content", attr: "label", fn: function () { return String(dma_qnaResultDetail.get("quesContn")); } },
        { childId: "td_40", attr: "__html", fn: function () { return ([String(String(dma_qnaResultDetail.get("ansContn")).split(String((dma_pageContext.get("NEW_LINE") ?? ""))).join("<br/>"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(String(dma_qnaResultDetail.get("ansContn")).split(String((dma_pageContext.get("NEW_LINE") ?? ""))).join("<br/>"))) : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_28_txt", fn: function(){ return (!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '완료'); } }, { id: "c_otherwise_29", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '완료'))); } }, { id: "c_otherwise_36", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '완료'))); } }, { id: "if_ansProgStatCd", fn: function(){ return (!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '처리중'); } }, { id: "c_when_57", fn: function(){ return (!(String(((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })()))).length === 0)); } }, { id: "c_otherwise_61", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })()))).length === 0)))); } }, { id: "c_when_69", fn: function(){ return (!(String(((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })()))).length === 0)); } }, { id: "c_otherwise_73", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })()))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txa_content_onkeyup
 * @description txa_content 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_content_onkeyup = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_content"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17102.txa_content_onkeyup' }); }
};

/**
 * @method
 * @name txa_content_onchange
 * @description txa_content 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_content_onchange = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_content"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17102.txa_content_onchange' }); }
};

/**
 * @method
 * @name img_45_onclick
 * @description img_45 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_45_onclick = async function(e){
    try {
        await scwin.modify('' + dma_qnaResultDetail.get("quesID") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17102.img_45_onclick' }); }
};

/**
 * @method
 * @name img_47_onclick
 * @description img_47 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_47_onclick = async function(e){
    try {
        await scwin.deleteGoURLReq('' + dma_qnaResultDetail.get("quesID") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17102.img_47_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_onclick
 * @description btn_GoURL 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_onclick = async function(e){
    try {
        await scwin.goURL('list')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17102.btn_GoURL_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_2_onclick
 * @description 「${qnaResultDetail.nextQnaResultVO.quesTitle}」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_2_onclick = async function(e){
    try {
        await scwin.goURL('detail',(String(((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO.quesID"); })())) == null ? '' : ((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO.quesID"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO.quesID"); })())) == null ? '' : ((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO.quesID"); })())))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17102.btn_GoURL_2_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_3_onclick
 * @description 「${qnaResultDetail.preQnaResultVO.quesTitle}」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_3_onclick = async function(e){
    try {
        await scwin.goURL('detail',(String(((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO.quesID"); })())) == null ? '' : ((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO.quesID"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO.quesID"); })())) == null ? '' : ((dma_qnaResultDetail.get("quesID") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO.quesID"); })())))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17102.btn_GoURL_3_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_GoURL
 * @description Go URL 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoURL = async function () {
    const sbmOptions = {
        id: "tx_fn_GoURL",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_GoURLReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {String} flag flag
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goURL = async function (flag, contnId) {
    if (flag === 'list') {
        $c.util.getComponent('dma_GoURLReq').set('method', 'searchQnaResult');
        (document.qnaResultDetailForm || { elements: [] }).action = 'qna.do';
        { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17101/jldfil17101.xml", { "method": 'searchQnaResult', "contnId": contnId }); } };
    } else {
        if (flag === 'detail') {
            $c.util.getComponent('dma_GoURLReq').set('method', 'searchQnaResultDetail');
            $c.util.getComponent('dma_GoURLReq').set('contnId', contnId);
            (document.qnaResultDetailForm || { elements: [] }).action = 'qna.do';
            { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17101/jldfil17101.xml", { "method": 'searchQnaResult', "contnId": contnId }); } };
        }
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} quesID quesID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (quesID) {
    const frm = (document.qnaResultDetailForm || { elements: [] });
    $c.util.getComponent('dma_GoURLReq').set('contnId', quesID);
    await scwin.checkByte($c.util.getComponent('txa_content'));
    frm.action = 'qna.do';
    $c.util.getComponent('dma_GoURLReq').set('method', 'updateQna');
    await scwin.tx_fn_Modify();
};

/**
 * @method
 * @name deleteGoURLReq
 * @description delete Go URLReq 처리
 * @param {String} quesID quesID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteGoURLReq = async function (quesID) {
    if (await $c.win.confirm("정말 삭제하시겠습니까?") === true) {
        const frm = (document.qnaResultDetailForm || { elements: [] });
        $c.util.getComponent('dma_GoURLReq').set('contnId', quesID);
        frm.action = 'qna.do';
        $c.util.getComponent('dma_GoURLReq').set('method', 'deleteQna');
        await scwin.tx_fn_Delete();
    } else {
        return;
    }
};

/**
 * @method
 * @name checkByte
 * @description check Byte 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkByte = async function (_obj) {
    const standardByte = 1990;
    const contnByte = scwin.getByte(_obj);
    const byteCntObj = $c.util.getComponent("txt_byteCnt");
    byteCntObj.innerText = "질의내용(" + (contnByte) + "/2000 byte)";
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
};

/**
 * @method
 * @name getByte
 * @description get Byte 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getByte = function (_obj) {
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0D') {
            iCounts++;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description calc Contn 처리
 * @param {*} _contn _contn
 * @param {*} _maximum _maximum
 * @returns {void}
 * @hidden N
 */
scwin.calcContn = function (_contn, _maximum) {
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (escape(ch) === '%0D') {
            inc = 1;
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                if (ch === '<' || ch === '>') {
                    inc = 4;
                } else {
                    inc = 1;
                }
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
};
